PACKET = {
    "entity_id": 1,
    "runtime_id": 2,
    "pos": v2225.Vec3(x=1.0, y=2.0, z=3.0),
    "rot": v2225.Vec2(x=4.0, y=5.0),
    "level_id": "lvl",
    "level_name": "world",
    "movement_settings": v2225.SyncedPlayerMovementSettings(rewind_history_size=40),
    "level_current_time": 100,
    "enable_item_stack_net_manager": True,
    "server_version": "1.21.0",
    "block_network_ids_are_hashes": True,
}

SETTINGS = {
    "seed": 7,
    "generator": v2225.GeneratorType.OVERWORLD,
    "game_difficulty": v2225.Difficulty.NORMAL,
    "default_spawn": v2225.BlockPos(x=0, y=64, z=0),
    "achievements_disabled": True,
    "multiplayer_game_intent": True,
    "lan_broadcast_intent": True,
    "xbl_broadcast_intent": v2225.GamePublishSetting.FRIENDS_ONLY,
    "platform_broadcast_intent": v2225.GamePublishSetting.FRIENDS_ONLY,
    "commands_enabled": True,
    "default_permissions": v2225.PlayerPermissionLevel.MEMBER,
    "server_chunk_tick_range": 4,
    "base_game_version": "1.21.0",
}

PRE_CEREAL_RULES = [
    v1001.pre_cereal.GameRule(name="dodaylightcycle", value=True),
    v1001.pre_cereal.GameRule(name="maxcommandchainlength", value=131070),
]

RULE_DATA = v2168.GameRulesChangedPacketData(
    rules=[
        v2168.GameRule(name="dodaylightcycle", value=True),
        v2168.GameRule(name="maxcommandchainlength", value=131070),
    ]
)

EDITOR_MIGRATED = v2225.StartGamePacket(
    **PACKET,
    settings=v2225.LevelSettings(
        **SETTINGS,
        time=1000,
        game_rules=RULE_DATA,
        editor_level_migration_version=v2225.EditorLevelMigrationVersion.EDITOR_ACHIEVEMENTS,
    ),
)

GOLDENS = [
    pytest.param(
        v975.StartGamePacket(**PACKET, settings=v975.LevelSettings(**SETTINGS, game_rules=PRE_CEREAL_RULES)),
        V975,
        id="v975",
    ),
    pytest.param(
        v1001.StartGamePacket(**PACKET, settings=v1001.LevelSettings(**SETTINGS, game_rules=PRE_CEREAL_RULES)),
        V1001,
        id="v1001",
    ),
    pytest.param(
        v2168.StartGamePacket(**PACKET, settings=v2168.LevelSettings(**SETTINGS, game_rules=RULE_DATA)),
        V2168,
        id="v2168",
    ),
]


@pytest.mark.parametrize("version", [v898, v975, v1001, v2168])
def test_start_game_is_packet_11(version):
    assert version.packets[11] is version.StartGamePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_start_game_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_start_game_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_2225_puts_the_editor_level_migration_version_ahead_of_the_time():
    older = v2193.StartGamePacket(**PACKET, settings=v2193.LevelSettings(**SETTINGS, time=1000, game_rules=RULE_DATA))
    old = bytes(older)
    new = bytes(EDITOR_MIGRATED)
    assert len(new) == len(old) + 1
    assert new[:47] + new[48:] == old


def test_2225_start_game_round_trips_its_editor_level_migration_version():
    assert v2225.StartGamePacket.from_bytes(bytes(EDITOR_MIGRATED)) == EDITOR_MIGRATED


def test_a_1001_body_does_not_decode_as_a_2168_one():
    with pytest.raises(ValueError, match="at byte"):
        v2168.StartGamePacket.from_bytes(V1001)


def test_a_2168_body_does_not_decode_as_a_1001_one():
    with pytest.raises(ValueError, match="at byte"):
        v1001.StartGamePacket.from_bytes(V2168)


def test_the_telemetry_ids_are_in_level_settings_at_898():
    packet = v898.StartGamePacket(
        settings=v898.LevelSettings(server_id="s", world_id="w", scenario_id="c", owner_id="o")
    )
    assert v898.StartGamePacket.from_bytes(bytes(packet)) == packet
